module ActionController;def self.add_renderer(key,&block)Renderers.add(key,&block);end;def self.remove_renderer(key)Renderers.remove(key);end;class MissingRenderer<LoadError;def initialize(format)super "No renderer defined for format: #{format}";end;end;module Renderers;extend ActiveSupport::Concern;RENDERERS=Set.new;included do class_attribute:_renderers,default:Set.new.freeze;end;module All;extend ActiveSupport::Concern;include Renderers;included do self._renderers=RENDERERS;end;end;def self.add(key,&block)define_method(_render_with_renderer_method_name(key),&block);RENDERERS<<key.to_sym;end;def self.remove(key)RENDERERS.delete(key.to_sym);method_name=_render_with_renderer_method_name(key);remove_possible_method(method_name);end;def self._render_with_renderer_method_name(key)"_render_with_renderer_#{key}";end;module ClassMethods;def use_renderers(*args)renderers=_renderers+args;self._renderers=renderers.freeze;end;alias use_renderer use_renderers;end;def render_to_body(options)_render_to_body_with_renderer(options)||super ;end;def _render_to_body_with_renderer(options)_renderers.each do |name|if options.key?(name);_process_options(options);method_name=Renderers._render_with_renderer_method_name(name);return send(method_name,options.delete(name),options);end;end;nil;end;add:json do |json,options|json_options=options.except(:callback,:content_type,:status);json=json.to_json(json_options) unless json.kind_of?(String);if options[:callback].present?;if media_type.nil?||media_type==Mime[:json];self.content_type=Mime[:js];end;"/**/#{options[:callback]}(#{json})";else self.content_type=Mime[:json] if media_type.nil?;json;end;end;add:js do |js,options|self.content_type=Mime[:js] if media_type.nil?;js.respond_to?(:to_js) ? js.to_js(options): js;end;add:xml do |xml,options|self.content_type=Mime[:xml] if media_type.nil?;xml.respond_to?(:to_xml) ? xml.to_xml(options): xml;end;end;end
